import {PIPELINES, SEGMENTS, seedState, todayISO, addDays, dayGap, textOf, active, audience, transitionError, pair} from './domain.mjs';

const KEY='diegoleon.control.demo.v1';
const $=(s,root=document)=>root.querySelector(s);
const $$=(s,root=document)=>[...root.querySelectorAll(s)];
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let storageAvailable=true, loadWarning=false;
function loadState(){try{const raw=localStorage.getItem(KEY);if(!raw)return seedState();const data=JSON.parse(raw);if(data.version!==1||!['team','tasks','clients','campaigns','referrals','partners','activity'].every(k=>Array.isArray(data[k])))throw Error('Invalid state');return data;}catch{loadWarning=true;return seedState();}}
let state=loadState();
let lang=state.language==='en'?'en':'es';
const t=(es,en)=>lang==='es'?es:en;
const txt=value=>textOf(value,lang);
const uid=prefix=>`${prefix}-${crypto.randomUUID().slice(0,8)}`;
const routeKinds={tasks:'tasks',crm:'clients',remarketing:'campaigns',referrals:'referrals',partners:'partners'};
const kindRoutes=Object.fromEntries(Object.entries(routeKinds).map(([a,b])=>[b,a]));
const icons={home:'M3 11 12 3l9 8M5 10v11h5v-7h4v7h5V10',tasks:'M9 6h12M9 12h12M9 18h12M3 6l1 1 2-2M3 12l1 1 2-2M3 18l1 1 2-2',crm:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2M9 11a4 4 0 1 0 0-8 4 4 0 0 0 0 8M17 4a4 4 0 0 1 0 8M22 21v-2a4 4 0 0 0-3-3.87',campaigns:'m3 11 18-7v16l-18-7v-2Zm4 3 2 7h3l-2-6M21 9h2',referrals:'M7 7h10M17 7l-4-4M17 7l-4 4M17 17H7M7 17l4-4M7 17l4 4',partners:'m8 12 3 3 5-6M5 3h14l2 4-3 13H6L3 7l2-4Z',team:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2M9 11a4 4 0 1 0 0-8 4 4 0 0 0 0 8M19 8v6M16 11h6',guide:'M4 4h6l2 2 2-2h6v16h-6l-2 2-2-2H4V4ZM12 6v16',search:'M21 21l-5-5M10 17a7 7 0 1 0 0-14 7 7 0 0 0 0 14',plus:'M12 5v14M5 12h14',arrow:'M5 12h14m-5-5 5 5-5 5',down:'M12 3v12m-5-5 5 5 5-5M5 17v4h14v-4',board:'M3 3h7v18H3V3Zm11 0h7v18h-7V3Z',list:'M8 6h13M8 12h13M8 18h13M3 6h1M3 12h1M3 18h1',clock:'M12 8v5l3 2M12 22a10 10 0 1 0 0-20 10 10 0 0 0 0 20',check:'m5 12 4 4L19 6',close:'m6 6 12 12M6 18 18 6',menu:'M4 6h16M4 12h16M4 18h16',mail:'M3 5h18v14H3V5Zm0 0 9 8 9-8',more:'M5 12h.01M12 12h.01M19 12h.01',flag:'M5 21V3h14l-3 5 3 5H5',link:'m10 13 4-4M8 16l-1 1a4 4 0 0 1-6-6l5-5a4 4 0 0 1 6 0M16 8l1-1a4 4 0 0 1 6 6l-5 5a4 4 0 0 1-6 0',info:'M12 10v7M12 7h.01M12 22a10 10 0 1 0 0-20 10 10 0 0 0 0 20',refresh:'M20 7v5h-5M4 17v-5h5M5 7a8 8 0 0 1 13-2l2 3M4 16l2 3a8 8 0 0 0 13-2'};
const icon=(name,cls='')=>`<svg class="icon ${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${icons[name]||icons.tasks}"/></svg>`;
const owner=id=>state.team.find(x=>x.id===id);
const ownerName=id=>owner(id)?.name??t('Sin asignar','Unassigned');
const initials=name=>String(name).trim().split(/\s+/).slice(0,2).map(s=>s[0]).join('').toUpperCase();
const avatar=(id,size='')=>`<span class="avatar ${owner(id)?.tone??'navy'} ${size}" title="${esc(ownerName(id))}">${esc(initials(ownerName(id)))}</span>`;
const stageInfo=(kind,id)=>PIPELINES[kind].stages.find(x=>x.id===id)??PIPELINES[kind].stages[0];
const dateValue=r=>r.dueDate||r.nextDate||'';
const isClosed=(kind,r)=>kind==='tasks'?r.stage==='done':kind==='clients'?['won','lost'].includes(r.stage):kind==='campaigns'?r.stage==='closed':kind==='referrals'?r.stage==='thanked':r.stage==='paused';
const isLate=(kind,r)=>dateValue(r)&&dateValue(r)<todayISO()&&!isClosed(kind,r);
function dateLabel(date){if(!date)return t('Sin fecha','No date');const gap=dayGap(date);if(gap===0)return t('Hoy','Today');if(gap===-1)return t('Mañana','Tomorrow');return new Intl.DateTimeFormat(lang==='es'?'es-CO':'en-US',{month:'short',day:'numeric',timeZone:'UTC'}).format(new Date(`${date}T12:00:00Z`));}
function fullDate(date){return new Intl.DateTimeFormat(lang==='es'?'es-CO':'en-US',{day:'numeric',month:'long',timeZone:'UTC'}).format(new Date(`${date}T12:00:00Z`));}
function titleOf(kind,r){if(kind==='referrals')return state.clients.find(c=>c.id===r.clientId)?.name??t('Cliente no disponible','Client unavailable');return txt(r.title||r.name);}
function referrerName(r){return (r.referrerType==='partner'?state.partners:state.clients).find(x=>x.id===r.referrerId)?.name??t('Sin origen','No source');}
function save(){state.language=lang;try{localStorage.setItem(KEY,JSON.stringify(state));storageAvailable=true;}catch{storageAvailable=false;toast(t('El navegador no pudo guardar. Los cambios se conservan en esta sesión.','Browser storage is unavailable. Changes remain in this session.'));}updateStorageLabel();}
function updateStorageLabel(){const label=$('#storageLabel');if(label)label.textContent=storageAvailable?t('Guardado en este navegador','Saved in this browser'):t('Solo en esta sesión','This session only');}
function log(kind,id,label){state.activity.unshift({id:uid('a'),kind,recordId:id,label,at:new Date().toISOString()});state.activity=state.activity.slice(0,60);}
let toastTimer;
function toast(message,undo){clearTimeout(toastTimer);$('#toast').innerHTML=`${icon('check')}<span>${esc(message)}</span>${undo?`<button id="undoAction">${t('Deshacer','Undo')}</button>`:''}`;$('#toast').classList.add('visible');if(undo)$('#undoAction').onclick=()=>{undo();$('#toast').classList.remove('visible');};toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),6000);}
function parseRoute(){const [path,query='']=(location.hash.slice(1)||'overview').split('?');return {page:['overview','team','guide',...Object.keys(routeKinds)].includes(path)?path:'overview',filters:Object.fromEntries(new URLSearchParams(query))};}
let route=parseRoute();
function go(page,filters={}){const qs=new URLSearchParams(Object.entries(filters).filter(([,v])=>v)).toString();const hash=`#${page}${qs?'?'+qs:''}`;if(location.hash===hash){route=parseRoute();render();}else location.hash=hash;}
function setFilter(key,value){if(value)route.filters[key]=value;else delete route.filters[key];const qs=new URLSearchParams(route.filters).toString();history.replaceState(null,'',`#${route.page}${qs?'?'+qs:''}`);renderBody();}
function filtered(kind){const f=route.filters;return active(state[kind]).filter(r=>(!f.owner||r.owner===f.owner)&&(!f.stage||r.stage===f.stage)&&(!f.priority||r.priority===f.priority)&&(!f.segment||r.segment===f.segment)&&(!f.due||(f.due==='late'?isLate(kind,r):f.due==='urgent'?dateValue(r)&&dateValue(r)<=todayISO()&&!isClosed(kind,r):dateValue(r)===todayISO()&&!isClosed(kind,r)))&&(!f.q||[titleOf(kind,r),r.email,r.source,ownerName(r.owner),txt(r.description),txt(r.nextAction)].join(' ').toLocaleLowerCase().includes(f.q.toLocaleLowerCase()))).sort((a,b)=>(dateValue(a)||'9999').localeCompare(dateValue(b)||'9999'));}
const navItems=[['overview','home','Vista general','Overview'],['tasks','tasks','Tareas del equipo','Team tasks'],['crm','crm','CRM comercial','Client CRM'],['remarketing','campaigns','Remarketing','Remarketing'],['referrals','referrals','Referidos','Referrals'],['partners','partners','Aliados & afiliación','Partners & affiliates'],['team','team','Equipo','Team'],['guide','guide','Guía de pipelines','Pipeline guide']];
function render(){
  document.documentElement.lang=lang;document.title=`${t('Control','Control')} · Dr. Diego León`;
  const nav=navItems.find(x=>x[0]===route.page);
  $('#app').innerHTML=`<aside class="sidebar" id="sidebar"><a href="#overview" class="brand"><span class="brand-symbol">D<span>↗</span></span><span>DR. DIEGO LEÓN<small>CONTROL / WORKSPACE</small></span></a><div class="workspace"><span class="workspace-mark">DL</span><span>Dental Group<small>${t('Espacio de demostración','Demo workspace')}</small></span><span class="workspace-dot"></span></div><span class="nav-label">${t('TU ESPACIO','YOUR WORKSPACE')}</span><nav aria-label="${t('Navegación principal','Main navigation')}">${navItems.map((n,i)=>`${i===3?`<span class="nav-label nav-break">${t('CRECIMIENTO','GROWTH')}</span>`:i===6?`<span class="nav-label nav-break">${t('ORGANIZACIÓN','ORGANIZATION')}</span>`:''}<a href="#${n[0]}" class="nav-item ${route.page===n[0]?'active':''}" ${route.page===n[0]?'aria-current="page"':''}>${icon(n[1])}<span>${t(n[2],n[3])}</span>${n[0]==='tasks'?`<span class="nav-count">${active(state.tasks).filter(x=>x.stage!=='done').length}</span>`:''}</a>`).join('')}</nav><div class="sidebar-bottom"><div class="demo-card"><span class="live-dot"></span><strong>${t('Propuesta interactiva','Interactive proposal')}</strong><p>${t('Un espacio para probar cómo trabajaría tu equipo.','A space to explore how your team could work.')}</p></div><button class="reset-link" data-action="reset">${icon('refresh')}${t('Restablecer demostración','Reset demo')}</button><div class="sidebar-person">${avatar('e1')}<span>Valentina Rojas<small>${t('Coordinación · Demo','Coordination · Demo')}</small></span></div></div></aside><button class="sidebar-shade" aria-label="${t('Cerrar navegación','Close navigation')}" data-action="close-nav"></button><div class="workspace-main"><header class="topbar"><div class="breadcrumb"><button class="icon-button mobile-menu" data-action="menu" aria-label="${t('Abrir navegación','Open navigation')}">${icon('menu')}</button><span>Workspace</span><span class="slash">/</span><strong>${t(nav[2],nav[3])}</strong></div><div class="top-actions"><span class="top-date">${fullDate(todayISO())}</span><span class="demo-pill">DEMO</span><button class="language" data-action="language" aria-label="${t('Switch to English','Cambiar a español')}">${lang.toUpperCase()} <span>/ ${lang==='es'?'EN':'ES'}</span></button>${avatar('e1','small')}</div></header><div class="demo-ribbon"><span>${icon('info')} ${t('Datos ficticios. Usa información de ejemplo. No se envían mensajes.','Fictional data. Use sample information. No messages are sent.')}</span><span id="storageLabel"></span></div><main id="main" tabindex="-1">${route.page==='overview'?overview():route.page==='team'?teamView():route.page==='guide'?guideView():pipelineView(routeKinds[route.page])}</main><footer class="app-footer"><span>DR. DIEGO LEÓN · CONTROL</span><span>${t('Propuesta independiente · Hora de Colombia (UTC−5)','Independent proposal · Colombia time (UTC−5)')}</span></footer></div>`;
  updateStorageLabel();renderBody();
}
function summaryMetric(label,value,foot,iconName){return `<div class="metric"><div class="metric-top"><span>${label}</span>${icon(iconName)}</div><strong>${value}</strong><small>${foot}</small></div>`;}
function overview(){
  const tasks=active(state.tasks),clients=active(state.clients),open=clients.filter(c=>!['won','lost'].includes(c.stage));
  const urgent=tasks.filter(x=>x.stage!=='done'&&x.dueDate<=todayISO()).sort((a,b)=>a.dueDate.localeCompare(b.dueDate));
  const late=tasks.filter(r=>isLate('tasks',r)).length,done=tasks.filter(x=>x.stage==='done').length;
  const dueClients=open.filter(c=>c.nextDate<=todayISO());
  return `<div class="page-title overview-title"><div><p class="eyebrow">${t('EL EQUIPO, EN SINTONÍA','YOUR TEAM, IN SYNC')}</p><h1>${t('Todo conectado.','Everything connected.')}</h1><p>${t('Una vista clara de las personas, los pendientes y las oportunidades.','A clear view of people, tasks and opportunities.')}</p></div><button class="primary" data-action="new" data-kind="tasks">${icon('plus')}${t('Nueva tarea','New task')}</button></div><section class="command-banner"><div class="banner-copy"><span class="eyebrow">${t('TU DÍA, CON INTENCIÓN','YOUR DAY, WITH INTENT')}</span><h2>${t('Cada detalle cuenta.<br>Cada paso, también.','Every detail matters.<br>So does every step.')}</h2><p>${t(`Tienes ${urgent.length} tareas para atender y ${dueClients.length} conversaciones por retomar.`,`You have ${urgent.length} tasks to address and ${dueClients.length} conversations to follow up.`)}</p><button class="banner-link" data-go="tasks" data-filter="due" data-value="urgent">${t('Organizar mi día','Organize my day')}${icon('arrow')}</button></div><div class="day-orbit" aria-hidden="true"><div class="orbit-ring"></div><div class="orbit-ring inner"></div><span class="orbit-star">✳</span></div><div class="banner-score"><span>${t('PROGRESO DEL EQUIPO','TEAM PROGRESS')}</span><strong>${done}<small>/ ${tasks.length}</small></strong><div class="progress"><i style="width:${tasks.length?done/tasks.length*100:0}%"></i></div><p>${t('tareas completadas en esta demo','tasks completed in this demo')}</p></div></section><div class="metrics">${summaryMetric(t('Conversaciones abiertas','Open conversations'),open.length,t('En el pipeline comercial','In the commercial pipeline'),'crm')}${summaryMetric(t('Tareas por atender','Tasks to address'),tasks.length-done,`${late} ${t('vencidas','overdue')}`,'tasks')}${summaryMetric(t('Referidos activos','Active referrals'),active(state.referrals).filter(x=>x.stage!=='thanked').length,t('Con origen registrado','With recorded attribution'),'referrals')}${summaryMetric(t('Aliados activos','Active partners'),active(state.partners).filter(x=>x.stage==='active').length,t('Acuerdo revisado','Agreement reviewed'),'partners')}</div><div class="overview-grid"><section class="panel priorities"><div class="panel-title"><div><h2>${t('Primero, lo importante','First, what matters')}</h2><p>${t('Vencidas y para hoy','Overdue and due today')}</p></div><button class="quiet" data-go="tasks">${t('Ver todas','View all')} ${icon('arrow')}</button></div>${urgent.length?urgent.slice(0,4).map(r=>`<button class="priority-row" data-action="edit" data-kind="tasks" data-id="${r.id}"><span class="task-status ${r.stage}"></span><span class="priority-copy"><strong>${esc(txt(r.title))}</strong><small>${esc(ownerName(r.owner))} <span>·</span> ${esc(txt(stageInfo('tasks',r.stage).name))}</small></span><span class="date-chip ${isLate('tasks',r)?'late':''}">${icon('clock')}${dateLabel(r.dueDate)}</span></button>`).join(''):empty(t('Todo al día','All caught up'),t('No hay tareas pendientes para hoy.','No pending tasks for today.'))}<div class="panel-foot"><span class="tiny-dot"></span>${t('Los cambios de etapa se reflejan en todo el espacio.','Stage changes update across the workspace.')}</div></section><section class="panel funnel"><div class="panel-title"><div><h2>${t('De conversación a conexión','From conversation to connection')}</h2><p>${t('Distribución actual del CRM','Current CRM distribution')}</p></div>${icon('crm')}</div>${PIPELINES.clients.stages.filter(s=>s.id!=='lost').map((s,i)=>{const count=clients.filter(c=>c.stage===s.id).length;return `<button class="funnel-row" data-go="crm" data-filter="stage" data-value="${s.id}"><span>${txt(s.name)}</span><strong>${count}</strong><i style="width:${Math.max(9,count/Math.max(1,clients.length)*100*3)}%;--bar-tone:${i}"></i></button>`;}).join('')}<div class="panel-foot">${t('Cada barra representa clientes en una etapa; no una tasa de conversión.','Bars show clients currently in each stage, not a conversion rate.')}</div></section></div><div class="overview-grid lower"><section class="panel"><div class="panel-title"><div><h2>${t('Un equipo, muchos detalles','One team, many details')}</h2><p>${t('Carga de trabajo por responsable','Workload by owner')}</p></div><button class="quiet" data-go="team">${t('Ver equipo','View team')}${icon('arrow')}</button></div>${active(state.team).map(e=>{const all=tasks.filter(x=>x.owner===e.id),completed=all.filter(x=>x.stage==='done').length;return `<button class="team-row" data-go="tasks" data-filter="owner" data-value="${e.id}">${avatar(e.id)}<span><strong>${esc(e.name)}</strong><small>${esc(txt(e.role))}</small></span><span class="team-progress"><span class="progress"><i style="width:${all.length?completed/all.length*100:0}%"></i></span><small>${completed}/${all.length} ${t('listas','done')}</small></span></button>`;}).join('')}</section><section class="panel"><div class="panel-title"><div><h2>${t('Así se mueve tu equipo','Your team in motion')}</h2><p>${t('Actividad de demostración','Demo activity')}</p></div>${icon('clock')}</div><div class="activity-list">${state.activity.slice(0,4).map(a=>`<button class="activity-row" data-action="edit" data-kind="${a.kind}" data-id="${a.recordId}"><span class="activity-dot"></span><span><strong>${esc(txt(a.label))}</strong><small>${new Intl.DateTimeFormat(lang==='es'?'es-CO':'en-US',{hour:'2-digit',minute:'2-digit',timeZone:'America/Bogota'}).format(new Date(a.at))}</small></span></button>`).join('')}</div></section></div>`;
}
function options(items,selected){return items.map(x=>`<option value="${esc(x[0])}" ${String(selected)===String(x[0])?'selected':''}>${esc(x[1])}</option>`).join('');}
const ownerOptions=selected=>options([["",t('Todo el equipo','All owners')],...active(state.team).map(x=>[x.id,x.name])],selected);
function pipelineView(kind){const p=PIPELINES[kind],f=route.filters;return `<div class="page-title"><div><p class="eyebrow">${t('PERSONAS. PROCESOS. PROGRESO.','PEOPLE. PROCESS. PROGRESS.')}</p><h1>${txt(p.name)}</h1><p>${txt(p.description)}</p></div><div class="title-actions"><button class="secondary" data-action="guide" data-kind="${kind}">${icon('guide')}<span>${t('Ver etapas','View stages')}</span></button><button class="primary" data-action="new" data-kind="${kind}">${icon('plus')}${kind==='tasks'?t('Nueva tarea','New task'):kind==='clients'?t('Nuevo cliente','New client'):kind==='campaigns'?t('Crear campaña','Create campaign'):kind==='referrals'?t('Registrar referido','Add referral'):t('Nuevo aliado','New partner')}</button></div></div>${kind==='campaigns'?`<div class="strategy-strip"><div>${icon('campaigns')}<span><strong>${t('Mensajes relevantes. Relaciones cuidadas.','Relevant messages. Thoughtful relationships.')}</strong><small>${t('La audiencia excluye contactos sin permiso para el canal o dados de baja. Los planes no envían mensajes.','Audiences exclude contacts without channel permission or opted out. Plans do not send messages.')}</small></span></div><span class="outline-pill">${t('Planificación','Planning')}</span></div>`:''}${kind==='referrals'?`<div class="strategy-strip"><div>${icon('referrals')}<span><strong>${t('Una recomendación que puedes seguir.','A referral you can follow.')}</strong><small>${t('Relaciona cada referido con un cliente o aliado y registra su autorización de contacto.','Link each referral to a client or partner and record contact authorization.')}</small></span></div></div>`:''}<div class="view-toolbar"><div class="view-switch" role="group" aria-label="${t('Tipo de vista','View layout')}"><button data-layout="board" aria-pressed="${f.layout!=='list'}" class="${f.layout!=='list'?'selected':''}">${icon('board')}${t('Tablero','Board')}</button><button data-layout="list" aria-pressed="${f.layout==='list'}" class="${f.layout==='list'?'selected':''}">${icon('list')}${t('Lista','List')}</button></div><label class="search-field">${icon('search')}<input id="viewSearch" data-filter="q" value="${esc(f.q||'')}" placeholder="${t('Buscar en esta vista…','Search this view…')}" aria-label="${t('Buscar registros','Search records')}" autocomplete="off"></label><button class="quiet export" data-action="export">${icon('down')}<span>${t('Exportar','Export')}</span></button></div><div class="filter-row"><label><span>${t('Responsable','Owner')}</span><select data-filter="owner" aria-label="${t('Filtrar por responsable','Filter by owner')}">${ownerOptions(f.owner)}</select></label><label><span>${t('Etapa','Stage')}</span><select data-filter="stage" aria-label="${t('Filtrar por etapa','Filter by stage')}">${options([['',t('Todas las etapas','All stages')],...p.stages.map(s=>[s.id,txt(s.name)])],f.stage)}</select></label><label><span>${t('Fecha','Date')}</span><select data-filter="due" aria-label="${t('Filtrar por fecha','Filter by date')}">${options([['',t('Todas las fechas','All dates')],['urgent',t('Vencidas y para hoy','Overdue & today')],['today',t('Para hoy','Due today')],['late',t('Vencidas','Overdue')]],f.due)}</select></label>${kind==='tasks'?`<label><span>${t('Prioridad','Priority')}</span><select data-filter="priority" aria-label="${t('Filtrar por prioridad','Filter by priority')}">${options([['',t('Todas','All')],['high',t('Alta','High')],['normal',t('Normal','Normal')],['low',t('Baja','Low')]],f.priority)}</select></label>`:''}${kind==='campaigns'?`<label><span>${t('Segmento','Segment')}</span><select data-filter="segment" aria-label="${t('Filtrar por segmento','Filter by segment')}">${options([['',t('Todos','All')],...SEGMENTS.map(s=>[s.id,txt(s.name)])],f.segment)}</select></label>`:''}<button class="clear-filters" data-action="clear-filters">${t('Limpiar filtros','Clear filters')}</button><span id="resultCount"></span></div><div id="recordsBody"></div><p class="board-hint">${icon('info')}${t('Arrastra las tarjetas o cambia su etapa desde el selector. Cada etapa tiene un criterio definido.','Drag cards or use their stage selector. Every stage has a defined criterion.')}</p>`;}
function empty(title,description,action=''){return `<div class="empty-state"><span>${icon('check')}</span><h3>${title}</h3><p>${description}</p>${action}</div>`;}
function renderBody(){const kind=routeKinds[route.page];if(!kind)return;const rows=filtered(kind);const count=$('#resultCount');if(count)count.textContent=`${rows.length} ${rows.length===1?t('registro','record'):t('registros','records')}`;$('#recordsBody').innerHTML=route.filters.layout==='list'?listView(kind,rows):boardView(kind,rows);}
function boardView(kind,rows){const stages=PIPELINES[kind].stages.filter(s=>!route.filters.stage||s.id===route.filters.stage);return `<div class="board" tabindex="0" role="region" aria-label="${t('Tablero de','Board:')} ${esc(txt(PIPELINES[kind].name))}" style="--cols:${stages.length}">${stages.map((s,index)=>{const items=rows.filter(r=>r.stage===s.id);return `<section class="kanban-column" data-drop="${s.id}" data-kind="${kind}"><header class="column-header"><span class="stage-dot ${s.tone}"></span><h2>${txt(s.name)}</h2><span class="column-count">${items.length}</span><button class="icon-button" data-action="new" data-kind="${kind}" data-stage="${s.id}" aria-label="${t('Añadir en','Add to')} ${esc(txt(s.name))}">${icon('plus')}</button></header><p class="column-rule">${txt(s.rule)}</p><div class="column-cards">${items.length?items.map(r=>recordCard(kind,r)).join(''):`<div class="column-empty">${t('Un próximo paso por comenzar.','A next step waiting to begin.')}</div>`}</div><button class="add-card" data-action="new" data-kind="${kind}" data-stage="${s.id}">${icon('plus')}${t('Añadir','Add')}</button></section>`;}).join('')}</div>`;}
function recordCard(kind,r){let middle='';
  if(kind==='tasks'){const completed=r.checklist.filter(x=>x.done).length;middle=`<p class="card-description">${esc(txt(r.description))}</p><div class="card-tags"><span class="tag priority-${r.priority}">${icon('flag')}${r.priority==='high'?t('Alta prioridad','High priority'):r.priority==='low'?t('Baja','Low'):t('Normal','Normal')}</span><span class="check-count">${icon('tasks')}${completed}/${r.checklist.length}</span></div>${r.clientId?`<div class="linked-label">${icon('link')}${esc(state.clients.find(c=>c.id===r.clientId)?.name||'')}</div>`:''}`;}
  if(kind==='clients')middle=`<p class="card-description">${esc(txt(r.interest))}</p><div class="card-tags"><span class="tag">${esc(r.source)}</span><span class="country">${esc(r.country)}</span></div><div class="next-action">${icon('arrow')}<span>${esc(txt(r.nextAction))}</span></div>`;
  if(kind==='campaigns'){const a=audience(state,r);middle=`<p class="card-description">${esc(txt(SEGMENTS.find(s=>s.id===r.segment)?.name))}</p><div class="audience-stat"><strong>${a.included.length}</strong><span>${t('contactos elegibles','eligible contacts')}</span></div><div class="card-tags"><span class="tag">${r.channel==='email'?'Email':'WhatsApp'}</span><span class="muted">${a.excluded.length} ${t('excluidos','excluded')}</span></div>`;}
  if(kind==='referrals')middle=`<p class="card-description">${t('Recomendado por','Referred by')} <strong>${esc(referrerName(r))}</strong></p><div class="card-tags"><span class="tag ${r.authorized?'positive':''}">${r.authorized?t('Contacto autorizado','Contact authorized'):t('Esperando autorización','Awaiting authorization')}</span></div><div class="next-action">${icon('arrow')}<span>${esc(txt(r.nextAction))}</span></div>`;
  if(kind==='partners'){const refs=active(state.referrals).filter(x=>x.referrerType==='partner'&&x.referrerId===r.id);middle=`<p class="card-description">${partnerType(r.type)}</p><div class="card-tags"><span class="code">${esc(r.code||'—')}</span><span>${refs.length} ${t('referidos','referrals')}</span></div><div class="next-action">${icon('arrow')}<span>${esc(txt(r.nextAction))}</span></div>`;}
  return `<article class="record-card" draggable="true" data-drag-id="${r.id}" data-kind="${kind}"><div class="card-topline"><span class="record-code">${esc(r.id.toUpperCase())}</span><span class="drag-handle" aria-hidden="true">⠿</span></div><button class="card-title" data-action="edit" data-kind="${kind}" data-id="${r.id}">${esc(titleOf(kind,r))}</button>${middle}<div class="card-footer"><span class="date-chip ${isLate(kind,r)?'late':''}">${icon('clock')}${dateLabel(dateValue(r))}</span>${avatar(r.owner,'small')}</div><label class="stage-select"><span class="sr-only">${t('Etapa de','Stage for')} ${esc(titleOf(kind,r))}</span><select data-move-id="${r.id}" data-kind="${kind}" aria-label="${t('Etapa de','Stage for')} ${esc(titleOf(kind,r))}">${options(PIPELINES[kind].stages.map(s=>[s.id,txt(s.name)]),r.stage)}</select></label></article>`;
}
function listView(kind,rows){return rows.length?`<div class="table-wrap"><table><thead><tr><th>${t('Registro','Record')}</th><th>${t('Responsable','Owner')}</th><th>${t('Etapa','Stage')}</th><th>${t('Próxima fecha','Next date')}</th><th>${t('Detalle','Detail')}</th></tr></thead><tbody>${rows.map(r=>`<tr><td><div class="table-name">${kind==='tasks'?`<input type="checkbox" data-complete="${r.id}" ${r.stage==='done'?'checked':''} aria-label="${t('Completar','Complete')} ${esc(titleOf(kind,r))}">`:''}<button data-action="edit" data-kind="${kind}" data-id="${r.id}"><strong>${esc(titleOf(kind,r))}</strong><small>${esc(r.id.toUpperCase())}</small></button></div></td><td><span class="owner-cell">${avatar(r.owner,'small')}${esc(ownerName(r.owner))}</span></td><td><select class="table-stage" data-move-id="${r.id}" data-kind="${kind}" aria-label="${t('Etapa de','Stage for')} ${esc(titleOf(kind,r))}">${options(PIPELINES[kind].stages.map(s=>[s.id,txt(s.name)]),r.stage)}</select></td><td><span class="date-chip ${isLate(kind,r)?'late':''}">${dateLabel(dateValue(r))}</span></td><td class="detail-cell">${kind==='clients'?esc(r.source):kind==='tasks'?`${r.checklist.filter(c=>c.done).length}/${r.checklist.length} ${t('subtareas','checklist')}`:kind==='campaigns'?`${audience(state,r).included.length} ${t('elegibles','eligible')}`:kind==='referrals'?esc(referrerName(r)):esc(r.code)}</td></tr>`).join('')}</tbody></table></div>`:empty(t('Nada por aquí, todavía','Nothing here yet'),t('Prueba otros filtros o crea el primer registro.','Try another filter or create the first record.'),`<button class="secondary" data-action="clear-filters">${t('Limpiar filtros','Clear filters')}</button>`);}
function partnerType(type){return txt({hospitality:pair('Alojamiento & hospitalidad','Accommodation & hospitality'),agency:pair('Agencia & viajes','Agency & travel'),creator:pair('Creador de contenido','Content creator'),community:pair('Comunidad','Community')}[type]||pair('Otro','Other'));}
function teamView(){return `<div class="page-title"><div><p class="eyebrow">${t('EL VALOR ESTÁ EN LAS PERSONAS','PEOPLE MAKE THE DIFFERENCE')}</p><h1>${t('Un equipo conectado.','One connected team.')}</h1><p>${t('Responsables visibles y cargas de trabajo que se pueden conversar.','Clear ownership and workloads you can discuss.')}</p></div><button class="primary" data-action="new" data-kind="team">${icon('plus')}${t('Añadir integrante','Add team member')}</button></div><div class="team-grid">${active(state.team).map(e=>{const all=active(state.tasks).filter(x=>x.owner===e.id),done=all.filter(x=>x.stage==='done').length,late=all.filter(x=>isLate('tasks',x)).length;return `<article class="team-card">${avatar(e.id,'large')}<h2>${esc(e.name)}</h2><p>${esc(txt(e.role))}</p><div class="team-numbers"><span><strong>${all.length-done}</strong>${t('pendientes','open')}</span><span><strong>${done}</strong>${t('terminadas','done')}</span><span><strong>${late}</strong>${t('vencidas','overdue')}</span></div><div class="progress"><i style="width:${all.length?done/all.length*100:0}%"></i></div><button class="secondary full" data-go="tasks" data-filter="owner" data-value="${e.id}">${t('Ver tareas','View tasks')}${icon('arrow')}</button><button class="quiet" data-action="edit" data-kind="team" data-id="${e.id}">${t('Editar integrante','Edit member')}</button></article>`;}).join('')}</div><div class="soft-note">${icon('info')}${t('Estos integrantes son ficticios. Añadir un integrante organiza la demo; no crea una cuenta ni envía invitaciones.','These team members are fictional. Adding a member organizes the demo; it does not create an account or send an invitation.')}</div>`;}
function guideView(){return `<div class="page-title"><div><p class="eyebrow">${t('CLARIDAD ANTES QUE VELOCIDAD','CLARITY BEFORE SPEED')}</p><h1>${t('Un siguiente paso claro.','A clear next step.')}</h1><p>${t('Cinco procesos distintos. Una sola forma de no perder el hilo.','Five distinct processes. One way to keep everything connected.')}</p></div></div><div class="guide-grid">${Object.entries(PIPELINES).map(([kind,p])=>`<section class="guide-panel"><div class="panel-title"><div><h2>${txt(p.name)}</h2><p>${txt(p.description)}</p></div><button class="quiet" data-go="${kindRoutes[kind]}">${t('Abrir','Open')}${icon('arrow')}</button></div><ol class="stage-guide">${p.stages.map(s=>`<li><span class="stage-dot ${s.tone}"></span><div><h3>${txt(s.name)}</h3><p>${txt(s.rule)}</p></div></li>`).join('')}</ol></section>`).join('')}</div>`;}

let editorReturnFocus=null;
function input(label,name,value='',type='text',extra=''){return `<label class="field"><span>${label}</span><input name="${name}" type="${type}" value="${esc(value)}" ${extra} ${type==='text'?'maxlength="160"':''}></label>`;}
function select(label,name,items,value,extra=''){return `<label class="field"><span>${label}</span><select name="${name}" aria-label="${esc(label)}" ${extra}>${options(items,value)}</select></label>`;}
function textarea(label,name,value,rows=3){return `<label class="field wide"><span>${label}</span><textarea name="${name}" rows="${rows}" maxlength="3000">${esc(value)}</textarea></label>`;}
function checkbox(label,name,value,help=''){return `<label class="check-field"><input type="checkbox" name="${name}" ${value?'checked':''}><span>${label}${help?`<small>${help}</small>`:''}</span></label>`;}
function openRecord(kind,id='',initial={}){
  const existing=id?state[kind]?.find(r=>r.id===id):null;
  if(id&&(!existing||existing.archived)){toast(t('Este registro está archivado o no está disponible.','This record is archived or unavailable.'));return;}
  const defaults={owner:'e1',stage:PIPELINES[kind]?.stages[0].id,dueDate:todayISO(),nextDate:todayISO(),lastContact:todayISO(),priority:'normal',checklist:[],notes:[],segment:'quiet',channel:'email',source:'Website',country:'Colombia',type:'hospitality',referrerType:'client',permissions:{email:false,whatsapp:false},...initial};
  const r=existing||defaults;
  if(!$('#editor').open)editorReturnFocus=document.activeElement;
  let fields='';
  if(kind==='team') fields=input(t('Nombre de ejemplo','Sample name'),'name',r.name,'text','required')+input(t('Rol en el equipo','Team role'),'role',txt(r.role),'text','required');
  else{
    if(kind==='referrals')fields+=select(t('Cliente referido','Referred client'),'clientId',[["",t('Seleccionar cliente del CRM','Select a CRM client')],...active(state.clients).map(c=>[c.id,c.name])],r.clientId,'required');
    else fields+=input(kind==='clients'||kind==='partners'?t('Nombre de ejemplo','Sample name'):t('Nombre','Title'),kind==='clients'||kind==='partners'?'name':'title',titleOf(kind,r),'text','required');
    fields+=select(t('Responsable','Owner'),'owner',active(state.team).map(e=>[e.id,e.name]),r.owner,'required');
    fields+=select(t('Etapa','Stage'),'stage',PIPELINES[kind].stages.map(s=>[s.id,txt(s.name)]),r.stage,'required');
    fields+=input(kind==='tasks'?t('Fecha de entrega','Due date'):t('Próximo seguimiento','Next follow-up'),kind==='tasks'?'dueDate':'nextDate',dateValue(r),'date','required');
    fields+=`<div class="stage-guidance wide" id="stageGuidance">${icon('info')}<span>${txt(stageInfo(kind,r.stage).rule)}</span></div>`;
    if(kind==='tasks')fields+=select(t('Prioridad','Priority'),'priority',[['high',t('Alta','High')],['normal',t('Normal','Normal')],['low',t('Baja','Low')]],r.priority)+select(t('Cliente relacionado','Related client'),'clientId',[["",t('Sin cliente vinculado','No linked client')],...active(state.clients).map(c=>[c.id,c.name])],r.clientId)+textarea(t('Resultado esperado','Expected outcome'),'description',txt(r.description))+`<section class="checklist-editor wide"><h3>${t('Lista de tareas','Checklist')}</h3><div id="checklistItems">${(r.checklist||[]).map(c=>checklistRow(c)).join('')}</div><div class="checklist-add"><input id="newChecklist" aria-label="${t('Nueva subtarea','New checklist item')}" maxlength="160" placeholder="${t('Añadir un paso…','Add a step…')}"><button type="button" class="secondary" data-action="add-check">${icon('plus')}<span class="sr-only">${t('Añadir subtarea','Add checklist item')}</span></button></div></section>`;
    if(kind==='clients')fields+=input('Email','email',r.email,'email','maxlength="254" autocomplete="off"')+input(t('Teléfono de ejemplo','Sample phone'),'phone',r.phone,'tel','maxlength="35" autocomplete="off"')+input(t('País','Country'),'country',r.country)+select(t('Origen','Source'),'source',['Website','WhatsApp','Instagram','Referral','Partner'].map(c=>[c,c==='Website'?t('Web','Website'):c==='Referral'?t('Referido','Referral'):c==='Partner'?t('Aliado','Partner'):c]),r.source)+input(t('Interés / contexto comercial','Interest / commercial context'),'interest',txt(r.interest))+input(t('Último contacto','Last contact'),'lastContact',r.lastContact,'date','required')+input(t('Fecha de valoración','Consultation date'),'appointment',r.appointment,'date')+input(t('Próxima acción','Next action'),'nextAction',txt(r.nextAction),'text','required')+`<fieldset class="permission-box wide"><legend>${t('Permisos para comunicaciones','Communication permissions')}</legend>${checkbox(t('Permiso para email','Email permission'),'emailPermission',r.permissions?.email)}${checkbox(t('Permiso para WhatsApp','WhatsApp permission'),'waPermission',r.permissions?.whatsapp)}${checkbox(t('Dado de baja: excluir de campañas','Opted out: exclude from campaigns'),'optOut',r.optOut)}<p>${t('En esta demo, registra solo permisos de ejemplo. No se usan datos médicos para segmentar.','Record sample permissions only in this demo. Medical information is not used for segmentation.')}</p></fieldset>`;
    if(kind==='campaigns')fields+=select(t('Segmento','Segment'),'segment',SEGMENTS.map(s=>[s.id,txt(s.name)]),r.segment)+select(t('Canal planificado','Planned channel'),'channel',[['email','Email'],['whatsapp','WhatsApp']],r.channel)+`<section id="audiencePreview" class="audience-preview wide">${audiencePreview(r)}</section>`+textarea(t('Mensaje de ejemplo','Sample message'),'message',txt(r.message),5)+`<div class="soft-note wide">${icon('info')}${t('Guardar prepara el plan. No envía emails, WhatsApp ni activa una automatización.','Saving prepares the plan. It does not send email or WhatsApp messages or activate automation.')}</div>`;
    if(kind==='referrals')fields+=select(t('Recomendado por','Referred by'),'referrer',[["",t('Seleccionar origen','Select source')],...active(state.clients).map(c=>[`client:${c.id}`,`${t('Cliente','Client')} · ${c.name}`]),...active(state.partners).map(c=>[`partner:${c.id}`,`${t('Aliado','Partner')} · ${c.name}`])],r.referrerId?`${r.referrerType}:${r.referrerId}`:'','required')+input(t('Fecha de valoración','Consultation date'),'appointment',r.appointment,'date')+input(t('Próxima acción','Next action'),'nextAction',txt(r.nextAction),'text','required')+`<div class="wide permission-box">${checkbox(t('El referido autorizó el contacto','The referred person authorized contact'),'authorized',r.authorized,t('Confirmación del referido, no solo de quien lo recomienda.','Confirmation from the referred person, not only their referrer.'))}</div>`;
    if(kind==='partners')fields+=select(t('Tipo de aliado','Partner type'),'type',['hospitality','agency','creator','community'].map(x=>[x,partnerType(x)]),r.type)+input('Email','email',r.email,'email','maxlength="254" autocomplete="off"')+input(t('Código de atribución','Attribution code'),'code',r.code,'text','pattern="[A-Za-z0-9-]+" title="Solo letras, números y guiones / Letters, numbers and hyphens"')+input(t('Próxima acción','Next action'),'nextAction',txt(r.nextAction),'text','required')+`<div class="wide permission-box">${checkbox(t('Acuerdo de colaboración revisado','Collaboration agreement reviewed'),'agreementReviewed',r.agreementReviewed,t('Marca una revisión de ejemplo. No firma acuerdos ni registra pagos.','Marks a sample review. It does not sign agreements or record payments.'))}</div>`;
    fields+=textarea(t('Añadir nota de seguimiento','Add a follow-up note'),'newNote','',2);
  }
  $('#editor').innerHTML=`<div class="editor-head"><span class="eyebrow">${id?esc(id.toUpperCase()):t('UN NUEVO COMIENZO','A NEW BEGINNING')}</span><button class="icon-button" data-action="close-editor" aria-label="${t('Cerrar ficha','Close record')}">${icon('close')}</button></div><div class="editor-heading"><h2 id="editorTitle">${kind==='team'?(id?t('Editar integrante','Edit member'):t('Nuevo integrante','New member')):id?esc(titleOf(kind,r)):t('Nuevo registro','New record')}</h2><p>${kind==='team'?t('Organiza responsables en esta demostración.','Organize owners in this demonstration.'):txt(PIPELINES[kind].description)}</p></div><form id="recordForm" data-kind="${kind}" data-id="${id}"><div class="editor-fields">${fields}</div><p id="formError" class="form-error" role="alert" hidden></p>${existing&&kind!=='team'?recordHistory(kind,existing):''}<div class="editor-footer">${id&&kind!=='team'?`<button type="button" class="archive-button" data-action="archive" data-kind="${kind}" data-id="${id}">${t('Archivar','Archive')}</button>`:'<span></span>'}<button type="button" class="secondary" data-action="close-editor">${t('Cancelar','Cancel')}</button><button type="submit" class="primary">${t('Guardar cambios','Save changes')}${icon('check')}</button></div></form>`;
  if(!$('#editor').open)$('#editor').showModal();document.body.classList.add('modal-open');$('#editor').scrollTop=0;
}
function checklistRow(c){return `<label class="checklist-row" data-check-id="${esc(c.id)}"><input type="checkbox" ${c.done?'checked':''}><span>${esc(txt(c.title))}</span><button type="button" class="icon-button" data-action="remove-check" aria-label="${t('Quitar subtarea','Remove checklist item')} ${esc(txt(c.title))}">${icon('close')}</button></label>`;}
function audiencePreview(campaign){const a=audience(state,campaign);return `<div class="audience-head"><h3>${t('Vista previa de audiencia','Audience preview')}</h3><span>${campaign.channel==='email'?'Email':'WhatsApp'}</span></div><div class="audience-totals"><span><strong>${a.included.length}</strong>${t('elegibles','eligible')}</span><span><strong>${a.excluded.length}</strong>${t('excluidos','excluded')}</span></div>${a.included.length?`<div class="audience-names">${a.included.map(c=>`<span>${esc(c.name)}</span>`).join('')}</div>`:`<p>${t('No hay contactos elegibles para este segmento y canal.','No eligible contacts for this segment and channel.')}</p>`}<small>${t('Se recalcula con los permisos y bajas actuales del CRM.','Recalculated from current CRM permissions and opt-outs.')}</small>`;}
function recordHistory(kind,r){const items=[...(r.notes||[]).map(n=>({at:n.at,label:n.text})),...state.activity.filter(a=>a.kind===kind&&a.recordId===r.id)].sort((a,b)=>b.at.localeCompare(a.at));return `<section class="record-history"><h3>${t('Historial del registro','Record history')}</h3>${items.length?items.slice(0,8).map(a=>`<div><span class="activity-dot"></span><p>${esc(txt(a.label))}<small>${new Intl.DateTimeFormat(lang==='es'?'es-CO':'en-US',{dateStyle:'short',timeStyle:'short',timeZone:'America/Bogota'}).format(new Date(a.at))}</small></p></div>`).join(''):`<p class="muted">${t('Las próximas actualizaciones aparecerán aquí.','Future updates will appear here.')}</p>`}</section>`;}
function closeEditor(){$('#editor').close();document.body.classList.remove('modal-open');if(editorReturnFocus?.isConnected)editorReturnFocus.focus({preventScroll:true});}
function formFailure(message){$('#formError').hidden=false;$('#formError').textContent=message;$('#formError').setAttribute('tabindex','-1');$('#formError').focus();}
function saveRecord(form){const kind=form.dataset.kind,id=form.dataset.id;const old=id?state[kind].find(r=>r.id===id):null;const f=new FormData(form);const val=name=>String(f.get(name)||'').trim();const checked=name=>f.get(name)==='on';let r={...(old||{}),id:id||uid(kind[0]),notes:old?.notes||[],archived:false};
  if(kind==='team'){if(!val('name')||!val('role'))return formFailure(t('Completa nombre y rol.','Complete name and role.'));r={...r,name:val('name'),role:val('role'),tone:old?.tone||'blue'};}
  else{
    r={...r,owner:val('owner'),stage:val('stage')};
    if(kind==='tasks'||kind==='campaigns')r.title=val('title');else if(kind==='clients'||kind==='partners')r.name=val('name');
    if((kind==='tasks'||kind==='campaigns')&&!r.title||(kind==='clients'||kind==='partners')&&!r.name)return formFailure(t('Escribe un nombre.','Enter a name.'));
    if(kind==='tasks'){r={...r,dueDate:val('dueDate'),priority:val('priority'),clientId:val('clientId'),description:val('description'),checklist:$$('.checklist-row',form).map(el=>({id:el.dataset.checkId,title:$('span',el).textContent,done:$('input',el).checked}))};}
    else r.nextDate=val('nextDate');
    if(kind==='clients')r={...r,email:val('email'),phone:val('phone'),country:val('country'),source:val('source'),interest:val('interest'),lastContact:val('lastContact'),appointment:val('appointment'),nextAction:val('nextAction'),permissions:{email:checked('emailPermission'),whatsapp:checked('waPermission')},optOut:checked('optOut')};
    if(kind==='campaigns')r={...r,segment:val('segment'),channel:val('channel'),message:val('message')};
    if(kind==='referrals'){const [referrerType,referrerId]=val('referrer').split(':');r={...r,clientId:val('clientId'),referrerType,referrerId,authorized:checked('authorized'),appointment:val('appointment'),nextAction:val('nextAction')};if(referrerType==='client'&&referrerId===r.clientId)return formFailure(t('El referido y quien recomienda deben ser personas distintas.','The referred client and referrer must be different people.'));if(active(state.referrals).some(x=>x.id!==id&&x.clientId===r.clientId))return formFailure(t('Este cliente ya tiene un referido registrado. Abre su ficha existente.','This client already has a referral record. Open the existing record.'));}
    if(kind==='partners'){r={...r,type:val('type'),email:val('email'),code:val('code').toUpperCase(),nextAction:val('nextAction'),agreementReviewed:checked('agreementReviewed')};if(r.code&&state.partners.some(p=>p.id!==id&&p.code===r.code))return formFailure(t('Ese código de atribución ya está asignado. Usa otro.','That attribution code is already assigned. Choose another.'));}
    const error=transitionError(kind,r,r.stage,state,lang);if(error)return formFailure(error);
    if(val('newNote'))r.notes=[...r.notes,{text:val('newNote'),at:new Date().toISOString()}];
  }
  if(old)state[kind][state[kind].findIndex(x=>x.id===id)]=r;else state[kind].unshift(r);
  if(kind!=='team')log(kind,r.id,pair(`${titleOf(kind,r)} · ${old?'registro actualizado':'registro creado'}`,`${titleOf(kind,r)} · ${old?'record updated':'record created'}`));
  save();closeEditor();render();toast(t('Cambios guardados en esta demo.','Changes saved in this demo.'));
}
function moveRecord(kind,id,next){const r=state[kind].find(x=>x.id===id&&!x.archived);if(!r)return;if(r.stage===next)return;const error=transitionError(kind,r,next,state,lang);if(error){toast(error);renderBody();return;}const previous=r.stage;r.stage=next;log(kind,id,pair(`${titleOf(kind,r)} → ${stageInfo(kind,next).name.es}`,`${titleOf(kind,r)} → ${stageInfo(kind,next).name.en}`));save();render();toast(t('Etapa actualizada.','Stage updated.'),()=>{r.stage=previous;log(kind,id,pair('Cambio de etapa deshecho','Stage change undone'));save();render();});}
function archive(kind,id){const r=state[kind].find(x=>x.id===id);if(!r)return;r.archived=true;log(kind,id,pair('Registro archivado','Record archived'));save();closeEditor();render();toast(t('Registro archivado.','Record archived.'),()=>{r.archived=false;save();render();});}
function showGuide(kind){const p=PIPELINES[kind];editorReturnFocus=document.activeElement;$('#editor').innerHTML=`<div class="editor-head"><span class="eyebrow">${t('CRITERIOS DE AVANCE','STAGE CRITERIA')}</span><button class="icon-button" data-action="close-editor" aria-label="${t('Cerrar ficha','Close record')}">${icon('close')}</button></div><div class="editor-heading"><h2 id="editorTitle">${txt(p.name)}</h2><p>${txt(p.description)}</p></div><ol class="stage-guide drawer-guide">${p.stages.map(s=>`<li><span class="stage-dot ${s.tone}"></span><div><h3>${txt(s.name)}</h3><p>${txt(s.rule)}</p></div></li>`).join('')}</ol>`;$('#editor').showModal();document.body.classList.add('modal-open');}
function exportView(){const kind=routeKinds[route.page];if(!kind)return;const rows=filtered(kind);const cell=value=>{let str=String(value??'');if(/^[=+@\-\t\r]/.test(str))str="'"+str;return `"${str.replace(/"/g,'""')}"`;};const headers=[t('Registro','Record'),t('Responsable','Owner'),t('Etapa','Stage'),t('Fecha','Date')];const csv='\uFEFF'+[headers,...rows.map(r=>[titleOf(kind,r),ownerName(r.owner),txt(stageInfo(kind,r.stage).name),dateValue(r)])].map(row=>row.map(cell).join(',')).join('\r\n');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8;'}));const a=document.createElement('a');a.href=url;a.download=`demo-${kind}-${todayISO()}.csv`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast(t('Vista exportada como CSV.','View exported as CSV.'));}
function confirmReset(){const dialog=$('#confirmDialog');dialog.innerHTML=`<span class="eyebrow">${t('VOLVER A EMPEZAR','START AGAIN')}</span><h2 id="confirmTitle">${t('¿Restablecer la demo?','Reset the demo?')}</h2><p>${t('Reemplazará los cambios de este navegador con los datos ficticios originales. Puedes deshacerlo justo después.','This replaces this browser’s changes with the original sample data. You can undo it immediately afterward.')}</p><div><button class="secondary" data-action="cancel-reset">${t('Cancelar','Cancel')}</button><button class="primary" data-action="confirm-reset">${t('Restablecer','Reset')}</button></div>`;dialog.showModal();}

document.addEventListener('click',event=>{
  if(event.target.closest('a[href="#main"]')){event.preventDefault();$('#main').focus();return;}
  const button=event.target.closest('button,[data-go]');if(!button)return;
  if(button.dataset.go){go(button.dataset.go,button.dataset.filter?{[button.dataset.filter]:button.dataset.value}:{});return;}
  if(button.dataset.layout){setFilter('layout',button.dataset.layout);$$('[data-layout]').forEach(b=>{b.classList.toggle('selected',b===button);b.setAttribute('aria-pressed',String(b===button));});return;}
  const action=button.dataset.action;
  if(action==='new')openRecord(button.dataset.kind,'',button.dataset.stage?{stage:button.dataset.stage}:{});
  if(action==='edit')openRecord(button.dataset.kind,button.dataset.id);
  if(action==='close-editor')closeEditor();
  if(action==='guide')showGuide(button.dataset.kind);
  if(action==='archive')archive(button.dataset.kind,button.dataset.id);
  if(action==='language'){lang=lang==='es'?'en':'es';save();render();}
  if(action==='menu')document.body.classList.toggle('nav-open');
  if(action==='close-nav')document.body.classList.remove('nav-open');
  if(action==='clear-filters')go(route.page,route.filters.layout?{layout:route.filters.layout}:{});
  if(action==='export')exportView();
  if(action==='add-check'){const field=$('#newChecklist');const value=field.value.trim();if(value){$('#checklistItems').insertAdjacentHTML('beforeend',checklistRow({id:uid('q'),title:value,done:false}));field.value='';field.focus();}}
  if(action==='remove-check')button.closest('.checklist-row').remove();
  if(action==='reset')confirmReset();
  if(action==='cancel-reset')$('#confirmDialog').close();
  if(action==='confirm-reset'){const backup=structuredClone(state);state=seedState();state.language=lang;save();$('#confirmDialog').close();go('overview');toast(t('Demo restablecida.','Demo reset.'),()=>{state=backup;save();render();});}
});
document.addEventListener('input',event=>{if(event.target.id==='viewSearch')setFilter('q',event.target.value);});
document.addEventListener('change',event=>{
  const field=event.target;if(field.dataset.filter)setFilter(field.dataset.filter,field.value);
  if(field.dataset.moveId)moveRecord(field.dataset.kind,field.dataset.moveId,field.value);
  if(field.dataset.complete)moveRecord('tasks',field.dataset.complete,field.checked?'done':'todo');
  if(field.form?.id==='recordForm'){
    const kind=field.form.dataset.kind;
    if(field.name==='stage')$('#stageGuidance').innerHTML=`${icon('info')}<span>${txt(stageInfo(kind,field.value).rule)}</span>`;
    if(kind==='campaigns'&&['segment','channel'].includes(field.name))$('#audiencePreview').innerHTML=audiencePreview({segment:field.form.elements.segment.value,channel:field.form.elements.channel.value});
  }
});
document.addEventListener('submit',event=>{if(event.target.id==='recordForm'){event.preventDefault();saveRecord(event.target);}});
document.addEventListener('keydown',event=>{if(event.key==='Enter'&&event.target.id==='newChecklist'){event.preventDefault();$('[data-action="add-check"]').click();}if(event.key==='Escape')document.body.classList.remove('nav-open');});
let dragged=null;
document.addEventListener('dragstart',event=>{const card=event.target.closest('[data-drag-id]');if(!card)return;dragged={kind:card.dataset.kind,id:card.dataset.dragId};event.dataTransfer.effectAllowed='move';event.dataTransfer.setData('text/plain',JSON.stringify(dragged));card.classList.add('dragging');});
document.addEventListener('dragover',event=>{const column=event.target.closest('[data-drop]');if(column&&dragged?.kind===column.dataset.kind){event.preventDefault();event.dataTransfer.dropEffect='move';$$('.drop-target').forEach(el=>el.classList.remove('drop-target'));column.classList.add('drop-target');}});
document.addEventListener('drop',event=>{const column=event.target.closest('[data-drop]');if(column&&dragged?.kind===column.dataset.kind){event.preventDefault();moveRecord(dragged.kind,dragged.id,column.dataset.drop);}dragged=null;$$('.drop-target,.dragging').forEach(el=>el.classList.remove('drop-target','dragging'));});
document.addEventListener('dragend',()=>{dragged=null;$$('.drop-target,.dragging').forEach(el=>el.classList.remove('drop-target','dragging'));});
$('#editor').addEventListener('close',()=>{document.body.classList.remove('modal-open');if(editorReturnFocus?.isConnected)editorReturnFocus.focus({preventScroll:true});});
window.addEventListener('hashchange',()=>{route=parseRoute();document.body.classList.remove('nav-open');render();window.scrollTo({top:0,behavior:'instant'});});
window.addEventListener('storage',event=>{if(event.key===KEY&&event.newValue){state=loadState();lang=state.language;render();toast(t('Demo actualizada desde otra pestaña.','Demo updated from another tab.'));}});
render();save();if(loadWarning)toast(t('Se cargaron los datos originales porque la copia local no era válida.','Original sample data was loaded because local data was invalid.'));
